SELECT CASE WHEN o.channel IN ('mobile', 'partner') THEN 'tier_1' ELSE 'other' END AS channel_group, MAX(oi.unit_price) AS max_unit_price, ROUND(AVG(oi.unit_price), 2) AS avg_unit_price FROM order_items oi INNER JOIN products p ON oi.product_id = p.id LEFT OUTER JOIN orders o ON o.id = oi.order_id WHERE p.brand IS NOT NULL GROUP BY CASE WHEN o.channel IN ('mobile', 'partner') THEN 'tier_1' ELSE 'other' END HAVING MAX(oi.unit_price) > 130 ORDER BY avg_unit_price;
